"""Scoped early Campaign3 claim review, retaining original occurrence identities."""
from pathlib import Path
from fractions import Fraction as F
import json,hashlib,copy
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-research-censoring-rev1';O.mkdir(exist_ok=True)
SOURCE='reference/RESEARCH.md'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[(463, 'STATUS', 'Capacity/applied/overflow retained; Correction2 supersedes original precision gate in four bounded cases.', 'RESOLVED label not exact posterior or general mean/precision sufficiency; source historical first-pass status remains.', ['CAMPAIGN3_LEARN_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (482, 'CORRECTION', 'Reject unjustified precision growth and truth-side Overflow learning; retire efficacy-recovery success criterion unsupported by censored data.', 'Mechanism conjecture about stalled timeline not controlled causal estimate: A/B addresses differ. Compatible bounds may constrain distributions; zero point movement not universal zero information.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md', 'CAMPAIGN3_EPI_QUALIFICATION.md']), (568, 'ORIGINAL-RESULTS', 'Original naive/censored fresh means equal; original point-confidence rule and17percent result preserved as historical predecessor.', 'Correction2 supersedes total-saturation confidence equality. Counterfactual improvement is actual bounded numeric result, not pure timing intervention or truth recovery proof.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (606, 'MATH', 'Exact applied+overflow decomposition retained; unconditional precision rationale explicitly retracted.', 'CDF incompatibility concerns exact transcendental output, not a proof that every rational probabilistic alternative is impossible. No law selected.', ['CAMPAIGN3_LEARN_QUALIFICATION.md', 'CAMPAIGN3_EPI_QUALIFICATION.md']), (633, 'COMPATIBILITY', 'Legacy point defaults preserve old tests; speculative Applied+kappaOverflow reward was trace-only.', '76 tests dated, not every untested behavior; trace visibility does not earn consumer or safe perceptual access. Later biology independent source semantics.', ['CAMPAIGN3_BIOLOGY_PUBLIC_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ008_CROSSWALK.md']), (655, 'VIVARIUM', 'Architecture-hosting question replaces research gated by play-frequency.', 'Learning observed clipped delta is not inherently a bug if target is experienced effect; do not fix by leaking true efficacy. No executed Vivarium parity proof.', ['CAMPAIGN3_EPI_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ009_CHECKPOINT.md']), (682, 'ROUTING', 'Overflow-magnitude route withdrawn; representational revisit followed salience/interpretation and now has bounded correction.', 'Historical PARTIAL is superseded for four fixtures only, not general inequality inference or posterior representation.', ['CAMPAIGN3_LEARN_QUALIFICATION.md']), (703, 'SUMMARY', 'Point confidence and bound evidence differ; keeping speculative trace outside cognition preserves comparison.', 'Summary open status historical; correction supplies narrow update fix, not universal rejection of richer posterior.', ['CAMPAIGN3_LEARN_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (741, 'CORRECTION2', 'Strict informative-bound gate handles weak, inconsistent, zero and fresh-prior repeated bounds without new state.', 'Full point-like precision on accepted bound remains approximation. Repeated established below-bound observations can still grow precision; equality/fresh-prior witness not deduplication.', ['CAMPAIGN3_LEARN_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (798, 'UPDATED-RESULTS', 'Corrected total-saturation confidence stays0; revised censored divergence0.1108 retained versus original0.1780.', 'Numeric improvement not guaranteed true-efficacy identification or matched timing-only causal effect. Unknown overflow information remains inaccessible.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (827, 'CORRECTION2-SUMMARY', 'Named fixtures protect bounded gate regressions and demonstrate an update fix can suffice without extra fields.', 'Compatibility-never-teaches wording only this candidate point gate; not general Bayesian principle.48percent result does not prove minimal sufficient state for all future queries.', ['CAMPAIGN3_LEARN_QUALIFICATION.md', 'CAMPAIGN3_UNCERTAINTY_QUALIFICATION.md'])]

rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE or not 463<=u['location']['startLine']<=855:continue
  assert u['location']['endLine']<=855
  _,name,claim,limits,paths=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],claim=name,disposition=claim,limits=limits,evidence=paths))
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes().startswith(raw)
lines=raw.decode('utf-8-sig').splitlines(keepends=True)
for r in rows:assert ''.join(lines[r['location']['startLine']-1:r['location']['endLine']])==r['text']
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={n for n in range(463,856) if lines[n-1].strip()}
evidence=[]
for n in sorted({n for s in specs for n in s[4]}):
 p=P/n;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
v=dict(status='HQ011 CENSORED LEARNING HISTORY REVIEWED; WIDER AUDIT OPEN',source=dict(path=SOURCE,frozenSha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,obligations=['RO-C3-001','RO-C3-008','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-012','RO-C3-013','RO-C3-014','RO-C3-015','RO-C3-016','RO-C3-017','RO-C3-019','RO-C3-020','RO-C3-021'],limits=['No fresh production simulation, test suite or build. Receipt bindings do not assert current source freshness for every old receipt.','Eleven reviewed claim groups retain independent public/component, law and historical correction scopes.'],nextGate='Reference RESEARCH856 onward: salience, interpretation and consolidation.')
save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),claimGroups=len(specs),indexedWholeOccurrenceLinks=964+len(rows),freshBehavioralTests=0,reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
